/**
 * @param {string} moves
 * @return {number}
 */
var furthestDistanceFromOrigin = function(moves) {
    let left = 0;
    let right = 0;
    let res = 0;

    for (const move of moves) {
        if (move === 'L') {
            left++;
            right = 0;
        } else if (move === 'R') {
            left = 0;
            right++;
        } else {
            left++;
            right++;
        }

        res = Math.max(res, left, right);
    }

    return res;
};

/**
 * @param {string} moves
 * @return {number}
 */
var furthestDistanceFromOrigin = function(moves) {
    let left = 0;
    let right = 0;

    for (const move of moves) {
        if (move === 'L') {
            left++;
        } else if (move === 'R') {
            right++;
        }
    }

    return moves.length - 2 * Math.min(left, right);
};

/**
 * @param {string} moves
 * @return {number}
 */
var furthestDistanceFromOrigin = function(moves) {
    let counter = 0;
    let same = 0;

    for (const move of moves) {
        if (move === 'L') {
            counter--;
        } else if (move === 'R') {
            counter++;
        } else {
            same++;
        }
    }

    return Math.abs(counter) + same;
};
